+/** Applies the `unrepresentable` setting at a site with no JSON Schema equivalent. Returns `true`
+ * when a handler supplied a JSON Schema, which has been merged into `json`. */
+export function handleUnrepresentable(
+  schema: schemas.$ZodType,
+  ctx: ToJSONSchemaContext,
+  message: string,
+  json?: JSONSchema.BaseSchema
+): boolean {
+  let action: ReturnType<UnrepresentableHandler<any>> = ctx.unrepresentable as any;
+  if (typeof action === "function") {
+    action = (ctx.unrepresentable as UnrepresentableHandler<any>)({
+      zodSchema: schema,
+      path: ctx.seen.get(schema)?.path ?? [],
+      message,
+    });
+  }
+  if (action === "any") return false;
+  if (action && typeof action === "object") {
+    if (json) Object.assign(json, action);
+    return true;
   }
+  throw new Error(message);
 }

